declarations.code:
template <class T, class Alloc, class... Args>

constexpr T *uninitialized_construct_using_allocator(T *p,

    const Alloc &alloc,

    Args &&...args);

intro:
Creates an object of the given type T by means of uses-allocator construction at the uninitialized memory location indicated by p.

Equivalent to

return std::apply(
    [&]<class... Xs>(Xs&&...xs)
    {
        return std::construct_at(p, std::forward<Xs>(xs)...);
    },
    std::uses_allocator_construction_args<T>(alloc, std::forward<Args>(args)...));

examples.code:
#include <memory>
#include <string>
#include <tuple>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    std::allocator<char> allocator;
    std::allocator_arg_t tag = std::allocator_arg;
    (void)tag;
    static_assert(std::uses_allocator_v<std::string, decltype(allocator)>);
    auto text = std::make_obj_using_allocator<std::string>(allocator, "hello");
    assert(text == "hello");
    auto args = std::uses_allocator_construction_args<std::string>(allocator, "world");
    auto other = std::make_from_tuple<std::string>(args);
    assert(other == "world");
    alignas(std::string) unsigned char storage[sizeof(std::string)];
    auto *pointer = reinterpret_cast<std::string *>(storage);
    std::uninitialized_construct_using_allocator(pointer, allocator, "test");
    assert(*pointer == "test");
    std::destroy_at(pointer);
}
